/// Set of keys generated by the schema simplification logic that represent
/// documentation or type metadata rather than actual message payload fields.
const Set<String> _schemaMetadataKeys = {
  '_doc',
  '_field_doc',
  '_type',
  'Doc',
  'Type',
  'Possible Values',
  'symbols',
};

final RegExp _arrayIndexSuffixRegex = RegExp(r'(\[\d+\])+$');

/// Returns `true` if the given schema key is a metadata property (like `_doc`)
/// rather than a data field.
bool isSchemaMetadataKey(String key) {
  return _schemaMetadataKeys.contains(key.trim());
}

/// Normalizes an Avro simplified schema tree path (e.g. `root.customer : Record.address : Record.city`)
/// into a clean, dot-separated JSON payload path (e.g. `customer.address.city`).
///
/// Strips `root.` prefix, removes `: Type` annotations from each path segment,
/// preserves array bracket indexing (e.g. `items[0]`), and returns an empty string
/// if the path targets a schema metadata property (e.g. `_doc`).
String normalizeSchemaFieldPath(String rawPath) {
  var p = rawPath.trim();
  if (p.startsWith('root.')) {
    p = p.substring(5);
  } else if (p == 'root') {
    return '';
  }

  final segments = p.split('.');
  final cleanSegments = <String>[];

  for (final seg in segments) {
    var s = seg.trim();
    if (s.isEmpty) continue;

    // Check if segment ends with array index e.g. "[0]" or "[2][0]"
    String arraySuffix = '';
    final match = _arrayIndexSuffixRegex.firstMatch(s);
    if (match != null) {
      arraySuffix = match.group(0)!;
      s = s.substring(0, match.start).trim();
    }

    // Strip ": TypeLabel" suffix
    final colonIdx = s.indexOf(':');
    if (colonIdx != -1) {
      s = s.substring(0, colonIdx).trim();
    }

    if (isSchemaMetadataKey(s)) {
      return '';
    }

    if (s.isNotEmpty) {
      cleanSegments.add('$s$arraySuffix');
    }
  }

  return cleanSegments.join('.');
}
